def test_task_4_cancellation_is_first_writer_wins():
    cancellation = CancellationToken()

    assert cancellation.cancel("operator interrupt") is True
    assert cancellation.cancel("later timeout") is False
    assert cancellation.cancelled is True
    assert cancellation.reason == "operator interrupt"

    with pytest.raises(AgentInterrupted) as caught:
        cancellation.raise_if_cancelled("model")

    assert caught.value.reason == "operator interrupt"
    assert caught.value.phase == "model"


