def test_task_4_terminal_append_linearizes_against_cancellation(tmp_path, monkeypatch):
    cancellation = CancellationToken()
    session = memory_session(tmp_path, "test-model")
    workspace = Workspace(ToolPolicy(tmp_path), cancellation=cancellation)
    reached_terminal_append = Event()
    cancellation_attempted = Event()
    cancellation_published = Event()
    original_append = session.append

    def cancel_at_terminal_boundary():
        assert reached_terminal_append.wait(timeout=1)
        cancellation_attempted.set()
        cancellation.cancel("late terminal cancellation")
        cancellation_published.set()

    def observed_append(event_type, **data):
        if event_type == "run_finished":
            reached_terminal_append.set()
            assert cancellation_attempted.wait(timeout=1)
            assert cancellation_published.wait(timeout=0.05) is False
        return original_append(event_type, **data)

    monkeypatch.setattr(session, "append", observed_append)
    canceller = Thread(target=cancel_at_terminal_boundary)
    canceller.start()
    result = run_agent(
        "inspect the project",
        responses('{"final":"done"}'),
        workspace,
        session=session,
        cancellation=cancellation,
    )
    canceller.join(timeout=1)

    assert canceller.is_alive() is False
    assert cancellation_published.is_set()
    assert cancellation.reason == "late terminal cancellation"
    assert result.completed is True
    assert session.events[-1].type == "run_finished"
    assert session.events[-1].data["completed"] is True


