def test_task_4_steering_appears_once_in_the_next_model_context(tmp_path):
    session = memory_session(tmp_path, "test-model")
    steering = SteeringHandle(session)
    workspace = Workspace(ToolPolicy(tmp_path))
    observed = []

    def generate(messages):
        observed.append([dict(message) for message in messages])
        if len(observed) == 1:
            steering.submit("also inspect filenames")
            return '{"tool":"list_files","path":"."}'
        return '{"final":"done"}'

    result = run_agent(
        "inspect the project",
        generate,
        workspace,
        AgentLimits(max_steps=2),
        session=session,
    )

    assert result.completed is True
    assert (
        sum(message["content"] == "also inspect filenames" for message in observed[0])
        == 0
    )
    assert (
        sum(message["content"] == "also inspect filenames" for message in observed[1])
        == 1
    )
    second_contents = [message["content"] for message in observed[1]]
    assert next(
        index
        for index, content in enumerate(second_contents)
        if content.startswith("Tool result:\n")
    ) < second_contents.index("also inspect filenames")
    durable = [
        event
        for event in session.events
        if event.type == "user_message" and event.data.get("kind") == "steering"
    ]
    assert len(durable) == 1
    queued = next(event for event in session.events if event.type == "steering_queued")
    assistant = next(
        event for event in session.events if event.type == "assistant_message"
    )
    first_result = next(
        event for event in session.events if event.type == "tool_result"
    )
    delivered = durable[0]
    event_ids = [event.id for event in session.events]
    assert event_ids.index(queued.id) < event_ids.index(assistant.id)
    assert event_ids.index(first_result.id) < event_ids.index(delivered.id)
    assert delivered.data["source_event_id"] == queued.id
    assert session.recover_incomplete_turns() == ()


