def test_task_4_terminal_final_linearizes_before_later_steering(tmp_path, monkeypatch):
    session = memory_session(tmp_path, "test-model")
    steering = SteeringHandle(session)
    workspace = Workspace(ToolPolicy(tmp_path))
    terminal_started = Event()
    submit_attempted = Event()
    submitted = []
    original_append = session.append

    def append_with_terminal_hook(event_type, **data):
        if event_type == "run_finished":
            terminal_started.set()
            assert submit_attempted.wait(2)
        return original_append(event_type, **data)

    def submit_after_terminal_lock_is_held():
        if terminal_started.wait(2):
            submit_attempted.set()
            submitted.append(steering.submit("late follow-up"))

    monkeypatch.setattr(session, "append", append_with_terminal_hook)
    submitter = Thread(target=submit_after_terminal_lock_is_held)
    submitter.start()
    result = run_agent(
        "inspect the project",
        responses('{"final":"done"}'),
        workspace,
        session=session,
    )
    submitter.join(2)

    assert not submitter.is_alive()
    assert result.completed is True
    assert len(submitted) == 1
    event_ids = [event.id for event in session.events]
    terminal = next(event for event in session.events if event.type == "run_finished")
    assert event_ids.index(terminal.id) < event_ids.index(submitted[0].id)
    assert session.pending_steering() == (submitted[0],)


