def test_task_4_concurrent_steering_delivery_is_exactly_once(tmp_path):
    session = memory_session(tmp_path, "test-model")
    SteeringHandle(session).submit("keep the API stable")
    deliveries = []
    errors = []

    def deliver():
        try:
            deliveries.append(session.deliver_pending_steering())
        except Exception as error:
            errors.append(error)

    threads = [Thread(target=deliver), Thread(target=deliver)]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()

    assert errors == []
    assert sorted(len(delivery) for delivery in deliveries) == [0, 1]
    assert (
        len(
            [
                event
                for event in session.events
                if event.type == "user_message" and event.data.get("kind") == "steering"
            ]
        )
        == 1
    )


