def test_task_4_interrupted_fsync_rolls_back_event_before_memory_publish(
    tmp_path, monkeypatch
):
    store = SessionStore(tmp_path, "test-model")
    session = store.create("a" * 32)
    assert session.path is not None
    before_bytes = session.path.read_bytes()
    before_events = session.events
    real_fsync = os.fsync
    interrupted = False

    def interrupt_after_fsync(descriptor):
        nonlocal interrupted
        real_fsync(descriptor)
        if not interrupted:
            interrupted = True
            raise KeyboardInterrupt

    monkeypatch.setattr(os, "fsync", interrupt_after_fsync)
    with pytest.raises(KeyboardInterrupt):
        session.append("user_message", content="not published", kind="task")

    assert session.path.read_bytes() == before_bytes
    assert session.events == before_events
    monkeypatch.setattr(os, "fsync", real_fsync)
    appended = session.append("user_message", content="published", kind="task")
    assert session.events[-1].id == appended.id


def test_task_4_load_recovers_verified_torn_session_tail(tmp_path):
    store = SessionStore(tmp_path, "test-model")
    session = store.create("a" * 32)
    session.append("user_message", content="task", kind="task")
    assert session.path is not None
    with session.path.open("ab") as file:
        file.write(b'{"partial":')
        file.flush()
        os.fsync(file.fileno())

    with pytest.raises(ValueError, match="partial event"):
        store.load(session.session_id, recover=False)

    loaded = store.load(session.session_id)

    assert loaded.path is not None
    assert loaded.path.read_bytes().endswith(b"\n")
    assert loaded.events[-1].type == "session_tail_recovered"
    assert loaded.events[-1].data["discarded_bytes"] == len(b'{"partial":')
    follow_up = loaded.append("user_message", content="continue", kind="followup")
    assert store.load(session.session_id, recover=False).events[-1] == follow_up


