class _FakeCache:
    def __init__(self):
        self.offset = 0
        self.released = 0

    def rewind(self, count):
        self.offset -= count

    def release(self):
        self.released += 1


class _InterruptingRewindCache(_FakeCache):
    def __init__(self):
        super().__init__()
        self.interrupt_rewind = False

    def rewind(self, count):
        self.offset -= count
        if self.interrupt_rewind:
            raise KeyboardInterrupt


class _InterruptingOffsetCache:
    def __init__(self):
        self.released = 0

    @property
    def offset(self):
        raise KeyboardInterrupt

    def release(self):
        self.released += 1


class _FakeArray:
    def __init__(self, values):
        self.values = list(values)

    def __getitem__(self, _key):
        return self


class _FakeLogits:
    def __getitem__(self, _key):
        return self


class _FakeScalar:
    def __init__(self, value):
        self.value = value

    def item(self):
        return self.value


class _FakeTokenizer:
    eos_token_id = 0

    def apply_chat_template(self, messages, **_kwargs):
        return "|".join(
            f"{message['role']}:{message['content']}" for message in messages
        )

    def encode(self, prompt, **_kwargs):
        return [(ord(character) % 251) + 1 for character in prompt]

    def decode(self, tokens):
        return ",".join(map(str, tokens))


class _UnexpectedModel:
    def __init__(self):
        self.calls = 0

    def __call__(self, *_args, **_kwargs):
        self.calls += 1
        raise AssertionError("pre-cancelled generation must not call the model")


class _CancellingModel:
    def __init__(self, cancellation):
        self.cancellation = cancellation

    def __call__(self, tokens, _offset, caches):
        for cache in caches:
            cache.offset += len(tokens.values)
        self.cancellation.cancel("stop decoding")
        return _FakeLogits()


class _StaticModel:
    def __call__(self, tokens, _offset, caches):
        for cache in caches:
            cache.offset += len(tokens.values)
        return _FakeLogits()


class _InterruptingModel:
    def __call__(self, tokens, _offset, caches):
        for cache in caches:
            cache.offset += len(tokens.values)
        raise KeyboardInterrupt


def _install_fake_mlx(monkeypatch):
    mlx = ModuleType("mlx")
    core = ModuleType("mlx.core")
    core.array = _FakeArray
    core.argmax = lambda _logits, axis: _FakeScalar(7)
    mlx.core = core
    monkeypatch.setitem(sys.modules, "mlx", mlx)
    monkeypatch.setitem(sys.modules, "mlx.core", core)


def test_task_4_pre_cancelled_generation_does_not_create_a_cache(monkeypatch):
    _install_fake_mlx(monkeypatch)
    cancellation = CancellationToken()
    cancellation.cancel("stop before generation")
    model = _UnexpectedModel()
    cache_factory_calls = 0

    def cache_factory():
        nonlocal cache_factory_calls
        cache_factory_calls += 1
        return [_FakeCache()]

    generation = GenerationSession(
        model,
        _FakeTokenizer(),
        cache_factory,
        max_tokens=2,
        cancellation=cancellation,
    )

    with pytest.raises(AgentInterrupted):
        generation(initial_messages("task", "system"))

    assert model.calls == 0
    assert cache_factory_calls == 0
    assert generation.cached_token_ids == ()


def test_task_4_cache_factory_iteration_interrupt_releases_yielded_caches(
    monkeypatch,
):
    _install_fake_mlx(monkeypatch)
