def test_task_5_workspace_journals_before_atomic_replace(tmp_path, monkeypatch):
    target = tmp_path / "value.txt"
    target.write_text("old", encoding="utf-8")
    session = memory_session(tmp_path, "test-model")
    workspace = Workspace(
        ToolPolicy(tmp_path, allow_writes=True),
        confirm_tool=lambda _action: True,
        session_log=session,
    )
    workspace.read_file("value.txt")
    original_write = workspace._atomic_write

    def checked_write(path, content, **write_state):
        assert target.read_text(encoding="utf-8") == "old"
        assert session.events[-1].type == "mutation_intent"
        assert not any(event.type == "mutation_committed" for event in session.events)
        original_write(path, content, **write_state)

    monkeypatch.setattr(workspace, "_atomic_write", checked_write)

    result = workspace.execute(
        ToolAction("write_file", {"path": "value.txt", "content": "new"})
    )

    event_types = [event.type for event in session.events]
    assert result == "wrote value.txt"
    assert target.read_text(encoding="utf-8") == "new"
    assert event_types.index("mutation_intent") < event_types.index(
        "mutation_committed"
    )


def test_task_5_parent_symlink_swap_cannot_write_outside_workspace(
    tmp_path, monkeypatch
):
    root = tmp_path / "workspace"
    approved_parent = root / "approved"
    displaced_parent = root / "approved-displaced"
    outside = tmp_path / "outside"
    approved_parent.mkdir(parents=True)
    outside.mkdir()
    target = approved_parent / "value.txt"
    outside_target = outside / "value.txt"
    target.write_text("approved old", encoding="utf-8")
    outside_target.write_text("outside unchanged", encoding="utf-8")
    outside_before = outside_target.read_bytes()
    outside_mode = stat.S_IMODE(outside_target.stat().st_mode)
    workspace = Workspace(
        ToolPolicy(root, allow_writes=True),
        confirm_tool=lambda _action: True,
    )
    workspace.read_file("approved/value.txt")
    original_write = workspace._atomic_write

    def swap_parent_then_write(path, content, **write_state):
        approved_parent.rename(displaced_parent)
        approved_parent.symlink_to(outside, target_is_directory=True)
        return original_write(path, content, **write_state)

    monkeypatch.setattr(workspace, "_atomic_write", swap_parent_then_write)
    result = workspace.execute(
        ToolAction(
            "write_file",
            {"path": "approved/value.txt", "content": "agent new"},
        )
    )

    assert result.startswith("error:")
    assert outside_target.read_bytes() == outside_before
    assert stat.S_IMODE(outside_target.stat().st_mode) == outside_mode
    assert (displaced_parent / "value.txt").read_text(encoding="utf-8") == (
        "approved old"
    )
    assert not list(outside.glob(".tiny-llm-agent-*"))


def test_task_5_final_component_substitution_is_not_overwritten(tmp_path, monkeypatch):
    target = tmp_path / "value.txt"
    target.write_text("approved old", encoding="utf-8")
    workspace = Workspace(
        ToolPolicy(tmp_path, allow_writes=True),
        confirm_tool=lambda _action: True,
    )
    workspace.read_file("value.txt")
    workspace_module = importlib.import_module(Workspace.__module__)
    real_replace = workspace_module.os.replace
    substituted = b"concurrent replacement"
    swapped = False

    def swap_target_before_backup(source, destination, **kwargs):
        nonlocal swapped
        if not swapped and source == "value.txt" and str(destination).endswith(".bak"):
            swapped = True
            target.unlink()
            target.write_bytes(substituted)
        return real_replace(source, destination, **kwargs)

    monkeypatch.setattr(workspace_module.os, "replace", swap_target_before_backup)
    result = workspace.execute(
        ToolAction("write_file", {"path": "value.txt", "content": "agent new"})
    )

    assert swapped is True
    assert result == "error: file changed since it was read; read it again"
    assert target.read_bytes() == substituted
    backups = list(tmp_path.glob(".tiny-llm-agent-*.bak"))
    assert len(backups) == 1
    assert backups[0].read_bytes() == substituted
    assert workspace.retained_recovery_files == {backups[0]}


def test_task_5_directory_fsync_failure_restores_verified_backup(tmp_path, monkeypatch):
    target = tmp_path / "value.txt"
    target.write_text("approved old", encoding="utf-8")
    workspace = Workspace(
        ToolPolicy(tmp_path, allow_writes=True),
        confirm_tool=lambda _action: True,
    )
    workspace.read_file("value.txt")
    workspace_module = importlib.import_module(Workspace.__module__)
    real_fsync = workspace_module.os.fsync
    failed = False

    def fail_first_directory_fsync(descriptor):
        nonlocal failed
        if stat.S_ISDIR(workspace_module.os.fstat(descriptor).st_mode) and not failed:
            failed = True
            raise OSError("injected directory fsync failure")
        return real_fsync(descriptor)

    monkeypatch.setattr(workspace_module.os, "fsync", fail_first_directory_fsync)

    result = workspace.execute(
        ToolAction("write_file", {"path": "value.txt", "content": "agent new"})
    )

    assert failed is True
    assert result == "error: injected directory fsync failure"
    assert target.read_text(encoding="utf-8") == "approved old"
    backups = list(tmp_path.glob(".tiny-llm-agent-*.bak"))
    failed_installs = list(tmp_path.glob(".tiny-llm-agent-*.failed"))
    assert len(backups) == len(failed_installs) == 1
    assert backups[0].read_text(encoding="utf-8") == "approved old"
    assert failed_installs[0].read_text(encoding="utf-8") == "agent new"
    assert workspace.retained_recovery_files == {
        backups[0],
        failed_installs[0],
    }


