def test_task_5_success_retains_late_writes_to_the_old_inode(
    tmp_path, monkeypatch, capsys
):
    target = tmp_path / "value.txt"
    target.write_text("approved old", encoding="utf-8")
    session = memory_session(tmp_path, "test-model")
    workspace = Workspace(
        ToolPolicy(tmp_path, allow_writes=True),
        session_log=session,
    )
    workspace.read_file("value.txt")
    workspace_module = importlib.import_module(Workspace.__module__)
    real_fsync = workspace_module.os.fsync
    held_descriptor = os.open(target, os.O_WRONLY)
    late_content = b"late external bytes"
    wrote_late = False

    def write_through_held_fd_before_directory_fsync(descriptor):
        nonlocal wrote_late
        if stat.S_ISDIR(os.fstat(descriptor).st_mode) and not wrote_late:
            wrote_late = True
            os.lseek(held_descriptor, 0, os.SEEK_SET)
            os.write(held_descriptor, late_content)
            os.ftruncate(held_descriptor, len(late_content))
            real_fsync(held_descriptor)
        return real_fsync(descriptor)

    monkeypatch.setattr(
        workspace_module.os,
        "fsync",
        write_through_held_fd_before_directory_fsync,
    )
    try:
        assert workspace.write_file("value.txt", "agent new") == "wrote value.txt"
    finally:
        os.close(held_descriptor)

    assert wrote_late is True
    assert target.read_text(encoding="utf-8") == "agent new"
    backups = list(tmp_path.glob(".tiny-llm-agent-*.bak"))
    assert len(backups) == 1
    assert backups[0].read_bytes() == late_content
    assert workspace.retained_recovery_files == {backups[0]}
    with pytest.raises(AgentError, match="not accessible"):
        workspace.read_file(backups[0].name)

    result = run_agent(
        "report the retained safety copy",
        responses('{"final":"reported"}'),
        workspace,
        session=session,
    )
    assert result.retained_recovery_files == (backups[0].name,)
    run_and_report(lambda: result, workspace)
    assert "Safety copies retained for manual inspection" in capsys.readouterr().out


@pytest.mark.parametrize(
    ("current", "expected_status", "expected_content"),
    [
        ("before", "not_applied", "old"),
        ("after", "committed", "new"),
        ("conflict", "conflict", "external"),
    ],
)
def test_task_5_pending_intent_recovery_never_overwrites(
    tmp_path, current, expected_status, expected_content
):
    target = tmp_path / "value.txt"
    target.write_text("old", encoding="utf-8")
    session = memory_session(tmp_path, "test-model")
    journal = MutationJournal(session, tmp_path)
    journal.record_intent("value.txt", "new")
    if current == "after":
        target.write_text("new", encoding="utf-8")
    elif current == "conflict":
        target.write_text("external", encoding="utf-8")
    bytes_before_recovery = target.read_bytes()

    recovered = MutationJournal(session, tmp_path).recover_pending()

    assert len(recovered) == 1
    assert recovered[0].status == expected_status
    assert target.read_bytes() == bytes_before_recovery
    assert target.read_text(encoding="utf-8") == expected_content


def test_task_5_cancellation_after_approval_leaves_a_recoverable_intent(tmp_path):
    target = tmp_path / "value.txt"
    target.write_text("old", encoding="utf-8")
    session = memory_session(tmp_path, "test-model")
    cancellation = CancellationToken()

    def approve_then_cancel(_action):
        cancellation.cancel("stop before replace")
        return True

    workspace = Workspace(
        ToolPolicy(tmp_path, allow_writes=True),
        confirm_tool=approve_then_cancel,
        session_log=session,
        cancellation=cancellation,
    )
    workspace.read_file("value.txt")

    with pytest.raises(AgentInterrupted) as caught:
        workspace.execute(
            ToolAction("write_file", {"path": "value.txt", "content": "new"})
        )

    assert caught.value.phase == "file_mutation"
    assert target.read_text(encoding="utf-8") == "old"
