def test_task_5_interrupt_after_replace_recovers_as_committed(tmp_path, monkeypatch):
    target = tmp_path / "value.txt"
    target.write_text("old", encoding="utf-8")
    session = memory_session(tmp_path, "test-model")
    cancellation = CancellationToken()
    workspace = Workspace(
        ToolPolicy(tmp_path, allow_writes=True),
        confirm_tool=lambda _action: True,
        session_log=session,
        cancellation=cancellation,
    )
    workspace.read_file("value.txt")
    original_write = workspace._atomic_write

    def replace_then_interrupt(path, content, **write_state):
        original_write(path, content, **write_state)
        cancellation.cancel("stop after replace")
        cancellation.raise_if_cancelled("file_mutation")

    monkeypatch.setattr(workspace, "_atomic_write", replace_then_interrupt)

    with pytest.raises(AgentInterrupted):
        workspace.execute(
            ToolAction("write_file", {"path": "value.txt", "content": "new"})
        )

    assert target.read_text(encoding="utf-8") == "new"
    recovered = workspace.journal.recover_pending()
    assert [result.status for result in recovered] == ["committed"]


def _journaled_write(journal, path, content):
    relative = path.relative_to(journal.workspace_root).as_posix()
    intent = journal.record_intent(relative, content)
    path.write_text(content, encoding="utf-8")
    path.chmod(intent.after_mode)
    journal.commit(intent)


def test_task_6_checkpoint_undo_restores_content_mode_and_created_files(tmp_path):
    target = tmp_path / "value.txt"
    created = tmp_path / "created.txt"
    target.write_text("old", encoding="utf-8")
    target.chmod(0o640)
    session = memory_session(tmp_path, "test-model")
    journal = MutationJournal(session, tmp_path)
    checkpoint = journal.create_checkpoint("before edits")

    _journaled_write(journal, target, "middle")
    _journaled_write(journal, target, "new")
    _journaled_write(journal, created, "created")
    session.append("command_started", command_id="1" * 32, argv=["inert-tool"])
    plan = journal.plan_undo(checkpoint.id)

    denied = journal.apply_undo(plan)
    assert denied.restored == ()
    assert denied.removed == ()
    assert target.read_text(encoding="utf-8") == "new"
    assert created.read_text(encoding="utf-8") == "created"
    assert any(
        "explicit operator confirmation" in warning for warning in denied.warnings
    )
    assert any("command side effects" in warning for warning in plan.warnings)

    applied = journal.apply_undo(plan, confirm=lambda _plan: True)

    assert set(applied.restored) == {"value.txt"}
    assert set(applied.removed) == {"created.txt"}
    assert applied.conflicts == ()
    assert target.read_text(encoding="utf-8") == "old"
    assert stat.S_IMODE(target.stat().st_mode) == 0o640
    assert not created.exists()
    started_artifacts = tuple(
        event.data["retained_recovery_path"]
        for event in session.events
        if event.type == "undo_change_started"
    )
    assert applied.retained_recovery_files == started_artifacts
    assert len(started_artifacts) == 2
    assert any(path.startswith(".tiny-llm-undo-remove-") for path in started_artifacts)
    assert any(path.startswith(".tiny-llm-undo-backup-") for path in started_artifacts)
    assert all((tmp_path / path).exists() for path in started_artifacts)
    assert session.events[-1].data["retained_recovery_files"] == list(started_artifacts)

    repeated = journal.apply_undo(
        plan,
        confirm=lambda _plan: pytest.fail("completed undo prompted again"),
    )
    assert repeated.restored == ()
    assert repeated.removed == ()
    assert repeated.conflicts == ()
    assert repeated.retained_recovery_files == started_artifacts
    assert "undo was already completed" in repeated.warnings
    assert session.events[-1].type == "undo_completed"

    _journaled_write(journal, target, "changed again")
    next_plan = journal.plan_undo(checkpoint)
    assert [change.path for change in next_plan.changes] == ["value.txt"]
    reapplied = journal.apply_undo(next_plan, confirm=lambda _plan: True)
    assert reapplied.conflicts == ()
    assert reapplied.restored == ("value.txt",)
    assert target.read_text(encoding="utf-8") == "old"


