@pytest.mark.parametrize("operation", ["remove_parent", "restore_ancestor"])
def test_task_6_undo_symlink_swap_never_touches_outside_workspace(
    tmp_path, monkeypatch, operation
):
    workspace = tmp_path / "workspace"
    outside = tmp_path / "outside"
    workspace.mkdir()
    outside.mkdir()
    if operation == "remove_parent":
        watched = workspace / "parent"
        watched.mkdir()
        target = watched / "created.txt"
        outside_target = outside / "created.txt"
        relative = "parent/created.txt"
    else:
        watched = workspace / "ancestor"
        (watched / "parent").mkdir(parents=True)
        (outside / "parent").mkdir()
        target = watched / "parent" / "value.txt"
        target.write_text("old", encoding="utf-8")
        outside_target = outside / "parent" / "value.txt"
        relative = "ancestor/parent/value.txt"
    outside_target.write_text("outside", encoding="utf-8")
    session = memory_session(workspace, "test-model")
    journal = MutationJournal(session, workspace)
    checkpoint = journal.create_checkpoint("before change")
    _journaled_write(
        journal, target, "created" if operation == "remove_parent" else "new"
    )
    plan = journal.plan_undo(checkpoint)
    detached = workspace / f"detached-{watched.name}"
    recovery_module = importlib.import_module(MutationJournal.__module__)
    real_open = recovery_module.os.open
    armed = False
    component_opens = 0

    def swap_on_destructive_traversal(path, flags, mode=0o777, *, dir_fd=None):
        nonlocal component_opens
        descriptor = real_open(path, flags, mode, dir_fd=dir_fd)
        if armed and dir_fd is not None and path == watched.name:
            component_opens += 1
            if component_opens == 2:
                watched.rename(detached)
                watched.symlink_to(outside, target_is_directory=True)
        return descriptor

    def arm_swap(_plan):
        nonlocal armed
        armed = True
        return True

    monkeypatch.setattr(recovery_module.os, "open", swap_on_destructive_traversal)

    result = journal.apply_undo(plan, confirm=arm_swap)

    assert component_opens >= 2
    assert outside_target.read_text(encoding="utf-8") == "outside"
    assert result.conflicts == (relative,)
    assert any("mutation parent changed" in warning for warning in result.warnings)
    if operation == "remove_parent":
        assert result.removed == ()
        assert (detached / "created.txt").read_text(encoding="utf-8") == "created"
    else:
        assert result.restored == ()
        assert (detached / "parent" / "value.txt").read_text(encoding="utf-8") == "new"


@pytest.mark.parametrize("operation", ["remove", "restore"])
def test_task_6_final_component_substitution_is_quarantined_not_mutated(
    tmp_path, monkeypatch, operation
):
    target = tmp_path / "value.txt"
    if operation == "restore":
        target.write_text("old", encoding="utf-8")
    session = memory_session(tmp_path, "test-model")
    journal = MutationJournal(session, tmp_path)
    checkpoint = journal.create_checkpoint("before change")
    _journaled_write(journal, target, "agent state")
    plan = journal.plan_undo(checkpoint)
    held = tmp_path / "held-agent-state.txt"
    recovery_module = importlib.import_module(MutationJournal.__module__)
    real_rename = recovery_module.os.rename
    armed = False
    substituted = False

    def substitute_before_quarantine(
        source,
        destination,
        *,
        src_dir_fd=None,
        dst_dir_fd=None,
    ):
        nonlocal substituted
        if armed and not substituted and source == target.name:
            substituted = True
            real_rename(target, held)
            target.write_text("attacker replacement", encoding="utf-8")
        return real_rename(
            source,
            destination,
            src_dir_fd=src_dir_fd,
            dst_dir_fd=dst_dir_fd,
        )

    def arm_substitution(_plan):
        nonlocal armed
        armed = True
        return True

    monkeypatch.setattr(recovery_module.os, "rename", substitute_before_quarantine)

    result = journal.apply_undo(plan, confirm=arm_substitution)

    assert substituted is True
    assert result.conflicts == ("value.txt",)
    assert target.read_text(encoding="utf-8") == "attacker replacement"
    assert held.read_text(encoding="utf-8") == "agent state"
    prefix = (
        ".tiny-llm-undo-remove-*.tmp"
        if operation == "remove"
        else ".tiny-llm-undo-backup-*.tmp"
    )
    retained = list(tmp_path.glob(prefix))
    assert len(retained) == 1
    assert retained[0].read_text(encoding="utf-8") == "attacker replacement"


