def test_task_6_branch_stops_at_ancestor_without_changing_parent_or_workspace(tmp_path):
    target = tmp_path / "value.txt"
    target.write_text("workspace bytes", encoding="utf-8")
    store = SessionStore(tmp_path, "test-model")
    parent = store.create("a" * 32)
    task = parent.append("user_message", content="original task", kind="task")
    parent.append("assistant_message", content='{"final":"later response"}')
    parent_events = parent.events
    assert parent.path is not None
    parent_bytes = parent.path.read_bytes()
    workspace_bytes = target.read_bytes()

    branch = store.branch(
        parent.session_id,
        task.id,
        new_session_id="b" * 32,
    )

    assert branch.session_id == "b" * 32
    assert branch.events[0].parent_id == task.id
    assert branch.events[1].type == "branch_created"
    assert branch.events[1].data["parent_session_id"] == parent.session_id
    assert branch.events[1].data["at_event_id"] == task.id
    assert branch.events[-1].type == "branch_completed"
    assert branch.messages("system")[-1]["content"] == "original task"
    assert all(
        "later response" not in message["content"]
        for message in branch.messages("system")
    )
    assert parent.events == parent_events
    assert parent.path.read_bytes() == parent_bytes
    assert target.read_bytes() == workspace_bytes


