class _EmptyStdout:
    def read(self, _size=-1):
        return b""

    def close(self):
        pass


class _SynchronousThread:
    def __init__(self, *, target, daemon):
        self.target = target

    def start(self):
        self.target()

    def join(self, timeout=None):
        pass

    def is_alive(self):
        return False


class _CompletedProcess:
    pid = 31337

    def __init__(self):
        self.stdout = _EmptyStdout()

    def wait(self, timeout=None):
        return 0

    def kill(self):
        pass


