def test_task_6_cancellation_during_command_start_never_launches(tmp_path, monkeypatch):
    command = ("inert-tool",)
    cancellation = CancellationToken()
    session = memory_session(tmp_path, "test-model")
    workspace = Workspace(
        ToolPolicy(tmp_path, allowed_commands=(command,)),
        session_log=session,
        cancellation=cancellation,
    )
    original_append = session.append
    popen_calls = 0
    workspace_module = importlib.import_module(Workspace.__module__)

    def cancel_after_durable_start(event_type, **data):
        event = original_append(event_type, **data)
        if event_type == "command_started":
            cancellation.cancel("stop before launch")
        return event

    def unexpected_popen(*_args, **_kwargs):
        nonlocal popen_calls
        popen_calls += 1
        raise AssertionError("a cancelled launch must not call Popen")

    monkeypatch.setattr(session, "append", cancel_after_durable_start)
    monkeypatch.setattr(workspace_module.subprocess, "Popen", unexpected_popen)

    with pytest.raises(AgentInterrupted) as caught:
        workspace.run_command(list(command))

    assert caught.value.phase == "command"
    assert popen_calls == 0
    assert workspace.command_side_effects_untracked is False
    assert workspace.command_cleanup_incomplete is False
    command_events = [
        event for event in session.events if event.type.startswith("command_")
    ]
    assert [event.type for event in command_events] == [
        "command_started",
        "command_finished",
    ]
    assert command_events[-1].data["launched"] is False


