class _CancellingProcess:
    pid = 4242

    def __init__(self, cancellation, command):
        self.cancellation = cancellation
        self.command = command
        self.stdout = _EmptyStdout()
        self.wait_calls = 0
        self.killed = False

    def wait(self, timeout=None):
        self.wait_calls += 1
        if self.wait_calls == 1:
            self.cancellation.cancel("stop command")
            raise subprocess.TimeoutExpired(self.command, timeout)
        return -9

    def kill(self):
        self.killed = True


def test_task_6_command_cancellation_uses_only_a_fake_process(tmp_path, monkeypatch):
    command = ("inert-tool",)
    cancellation = CancellationToken()
    process = _CancellingProcess(cancellation, command)
    killed_groups = []
    workspace_module = importlib.import_module(Workspace.__module__)
    monkeypatch.setattr(
        workspace_module.subprocess,
        "Popen",
        lambda *_args, **_kwargs: process,
    )
    monkeypatch.setattr(workspace_module, "Thread", _SynchronousThread)
    monkeypatch.setattr(
        workspace_module.os,
        "killpg",
        lambda pid, signal_number: killed_groups.append((pid, signal_number)),
    )
    workspace = Workspace(
        ToolPolicy(
            tmp_path,
            allowed_commands=(command,),
            command_timeout_seconds=1,
        ),
        cancellation=cancellation,
    )

    with pytest.raises(AgentInterrupted) as caught:
        workspace.run_command(list(command))

    assert caught.value.phase == "command"
    assert killed_groups == [(process.pid, 9)]
    assert process.wait_calls == 2
    assert workspace.command_side_effects_untracked is True


