@pytest.mark.parametrize("operation", ["remove", "restore"])
def test_task_6_undo_retains_public_inode_changed_through_held_fd(
    tmp_path, monkeypatch, operation
):
    target = tmp_path / "value.txt"
    if operation == "restore":
        target.write_text("old", encoding="utf-8")
    session = memory_session(tmp_path, "test-model")
    journal = MutationJournal(session, tmp_path)
    checkpoint = journal.create_checkpoint("before change")
    _journaled_write(journal, target, "agent state")
    plan = journal.plan_undo(checkpoint)
    held_descriptor = os.open(target, os.O_WRONLY)
    recovery_module = importlib.import_module(MutationJournal.__module__)
    real_fsync = recovery_module.os.fsync
    late_content = b"late external bytes"
    wrote_late = False

    def write_through_held_fd_after_validation(descriptor):
        nonlocal wrote_late
        if stat.S_ISDIR(os.fstat(descriptor).st_mode) and not wrote_late:
            wrote_late = True
            os.lseek(held_descriptor, 0, os.SEEK_SET)
            os.write(held_descriptor, late_content)
            os.ftruncate(held_descriptor, len(late_content))
            real_fsync(held_descriptor)
        return real_fsync(descriptor)

    monkeypatch.setattr(
        recovery_module.os,
        "fsync",
        write_through_held_fd_after_validation,
    )
    try:
        result = journal.apply_undo(plan, confirm=lambda _plan: True)
    finally:
        os.close(held_descriptor)

    assert wrote_late is True
    assert result.conflicts == ()
    if operation == "remove":
        assert result.removed == ("value.txt",)
        assert not target.exists()
        pattern = ".tiny-llm-undo-remove-*.tmp"
    else:
        assert result.restored == ("value.txt",)
        assert target.read_text(encoding="utf-8") == "old"
        pattern = ".tiny-llm-undo-backup-*.tmp"
    retained = list(tmp_path.glob(pattern))
    assert len(retained) == 1
    assert retained[0].read_bytes() == late_content
    with pytest.raises(AgentError, match="protected"):
        journal.record_intent(retained[0].name, "must not replace evidence")
    with pytest.raises(AgentError, match="not accessible"):
        Workspace(ToolPolicy(tmp_path)).read_file(retained[0].name)


@pytest.mark.parametrize("operation", ["remove", "restore"])
def test_task_6_base_exception_after_public_quarantine_restores_name_and_evidence(
    tmp_path, monkeypatch, operation
):
    target = tmp_path / "value.txt"
    if operation == "restore":
        target.write_text("old", encoding="utf-8")
    session = memory_session(tmp_path, "test-model")
    journal = MutationJournal(session, tmp_path)
    checkpoint = journal.create_checkpoint("before change")
    _journaled_write(journal, target, "agent state")
    plan = journal.plan_undo(checkpoint)
    recovery_module = importlib.import_module(MutationJournal.__module__)

    if operation == "remove":
        real_rename = recovery_module.os.rename
        interrupted = False

        def interrupt_after_remove_quarantine(
            source,
            destination,
            *,
            src_dir_fd=None,
            dst_dir_fd=None,
        ):
            nonlocal interrupted
            result = real_rename(
                source,
                destination,
                src_dir_fd=src_dir_fd,
                dst_dir_fd=dst_dir_fd,
            )
            if source == "value.txt" and not interrupted:
                interrupted = True
                raise KeyboardInterrupt
            return result

        monkeypatch.setattr(
            recovery_module.os,
            "rename",
            interrupt_after_remove_quarantine,
        )
    else:
        real_stat = recovery_module.os.stat
        interrupted = False

        def interrupt_before_restore_backup_identity(
            path,
            *,
            dir_fd=None,
            follow_symlinks=True,
        ):
            nonlocal interrupted
            if (
                isinstance(path, str)
                and path.startswith(".tiny-llm-undo-backup-")
                and not interrupted
            ):
                interrupted = True
                raise KeyboardInterrupt
            return real_stat(
                path,
                dir_fd=dir_fd,
                follow_symlinks=follow_symlinks,
            )

        monkeypatch.setattr(
            recovery_module.os,
            "stat",
            interrupt_before_restore_backup_identity,
        )

    with pytest.raises(KeyboardInterrupt):
        journal.apply_undo(plan, confirm=lambda _plan: True)

    assert interrupted is True
    assert target.read_text(encoding="utf-8") == "agent state"
    started = [event for event in session.events if event.type == "undo_change_started"]
    assert len(started) == 1
    retained_path = started[0].data["retained_recovery_path"]
    retained = tmp_path / retained_path
    assert retained.read_text(encoding="utf-8") == "agent state"

    if operation == "remove":
        monkeypatch.setattr(recovery_module.os, "rename", real_rename)
    else:
        monkeypatch.setattr(recovery_module.os, "stat", real_stat)
    resumed = journal.apply_undo(
        plan,
        confirm=lambda _plan: pytest.fail("unsafe hard-linked target prompted"),
    )

    assert resumed.conflicts == ("value.txt",)
    assert resumed.retained_recovery_files == (retained_path,)


def test_task_6_tampered_retained_recovery_event_fails_closed(tmp_path, monkeypatch):
    target = tmp_path / "value.txt"
    target.write_text("old", encoding="utf-8")
