def test_task_6_retry_returns_union_of_every_started_retained_path(
    tmp_path, monkeypatch
):
    target = tmp_path / "value.txt"
    target.write_text("old", encoding="utf-8")
    session = memory_session(tmp_path, "test-model")
    journal = MutationJournal(session, tmp_path)
    checkpoint = journal.create_checkpoint("before edit")
    _journaled_write(journal, target, "agent state")
    plan = journal.plan_undo(checkpoint)
    original_restore = journal._restore_exact

    def fail_before_restore(_change, *, backup_name):
        raise AgentError(f"injected before {backup_name}")

    monkeypatch.setattr(journal, "_restore_exact", fail_before_restore)
    failed = journal.apply_undo(plan, confirm=lambda _plan: True)

    assert failed.conflicts == ("value.txt",)
    assert len(failed.retained_recovery_files) == 1
    assert not (tmp_path / failed.retained_recovery_files[0]).exists()

    monkeypatch.setattr(journal, "_restore_exact", original_restore)
    resumed = journal.apply_undo(plan, confirm=lambda _plan: True)
    started_artifacts = tuple(
        dict.fromkeys(
            event.data["retained_recovery_path"]
            for event in session.events
            if event.type == "undo_change_started"
        )
    )

    assert resumed.conflicts == ()
    assert resumed.restored == ("value.txt",)
    assert len(started_artifacts) == 2
    assert resumed.retained_recovery_files == started_artifacts
    assert session.events[-1].data["retained_recovery_files"] == list(started_artifacts)

    repeated = journal.apply_undo(
        plan,
        confirm=lambda _plan: pytest.fail("completed retry prompted again"),
    )
    assert repeated.retained_recovery_files == started_artifacts


def test_task_6_temp_cleanup_base_exception_cannot_skip_backup_restoration(
    tmp_path, monkeypatch
):
    target = tmp_path / "value.txt"
    target.write_text("old", encoding="utf-8")
    session = memory_session(tmp_path, "test-model")
    journal = MutationJournal(session, tmp_path)
    checkpoint = journal.create_checkpoint("before edit")
    _journaled_write(journal, target, "agent state")
    plan = journal.plan_undo(checkpoint)
    recovery_module = importlib.import_module(MutationJournal.__module__)
    real_link = recovery_module.os.link
    original_cleanup = journal._unlink_internal_if_identity
    install_failed = False
    cleanup_interrupted = False

    def fail_install_after_backup(
        source,
        destination,
        *,
        src_dir_fd=None,
        dst_dir_fd=None,
        follow_symlinks=True,
    ):
        nonlocal install_failed
        if (
            source.startswith(".tiny-llm-undo-")
            and not source.startswith(".tiny-llm-undo-backup-")
            and destination == "value.txt"
        ):
            install_failed = True
            raise OSError("injected install failure")
        return real_link(
            source,
            destination,
            src_dir_fd=src_dir_fd,
            dst_dir_fd=dst_dir_fd,
            follow_symlinks=follow_symlinks,
        )

    def interrupt_internal_temp_cleanup(parent, name, expected_identity):
        nonlocal cleanup_interrupted
        cleanup_interrupted = True
        raise KeyboardInterrupt

    monkeypatch.setattr(recovery_module.os, "link", fail_install_after_backup)
    monkeypatch.setattr(
        journal,
        "_unlink_internal_if_identity",
        interrupt_internal_temp_cleanup,
    )

    with pytest.raises(KeyboardInterrupt):
        journal.apply_undo(plan, confirm=lambda _plan: True)

    assert install_failed is True
    assert cleanup_interrupted is True
    assert target.read_text(encoding="utf-8") == "agent state"
    started = next(
        event for event in session.events if event.type == "undo_change_started"
    )
    retained_path = started.data["retained_recovery_path"]
    assert (tmp_path / retained_path).read_text(encoding="utf-8") == "agent state"

    monkeypatch.setattr(recovery_module.os, "link", real_link)
    monkeypatch.setattr(
        journal,
        "_unlink_internal_if_identity",
        original_cleanup,
    )
    resumed = journal.apply_undo(
        plan,
        confirm=lambda _plan: pytest.fail("unsafe hard-linked target prompted"),
    )

    assert resumed.conflicts == ("value.txt",)
    assert resumed.retained_recovery_files == (retained_path,)
